INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Ҷустуҷӯи хараҷатҳо ва баҳодиҳии иқтисодӣ барои карпории сабазӣ бо истифода аз усули нӯраи дарак дар ҳуҷайраи як гектар. Мусоид барои реҷакунии иқтисодии фермерон.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
