INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Чаро фенугрик ба осории дақиқ ниёз дорад?</h2>\n<p>Фенугрик (Fenugreek) яке аз наъмҳои доруӣ ва хӯроки пуртақозост, ки решаи он ба чуқурии зиёд дар хок ҷойгир мешавад. Аммо барои расидан ба ҳадди олии <strong>ҳосилоти фенугрик дар гектар бо наварии ғиринкӣ</strong>, идоракунии оросиш нақши ҳарифро боз мекунад. Ин нам на ба стресс оби ҳассос аст ва тағйирот намуди хок метавонад ба сифати дунб ва реша таъсири манфӣ расонад. Системаҳои оросиши сатҳӣ одатан боиси ифтиори об ва коҳиши якхунгии нам дар ҳудуди реша мешаванд. Баръакс, истифодаи технологияҳои навзодшудаи оросиш, ба монанди наварии ғиринкӣ, имконияти тақсимоти якхунаи обро фароҳам меорад. Инчунин, таҳқиқоти охирӣ нишон медиҳанд, ки дар коркунҳои мушабиҳ, ба монанди триҷини сиёҳ, тағйир додани намуди системаи оросиш ба раваҷи назаррас дар самаранокӣ оварда мерасонад ва фенугрик низ аз ин қоида истисно нест. Бинобар ин, диққат ба решаи мувофиқ ва ғизоидории ҳамзамони об ва одак, калиди асосӣ дар дастрасии потенсиали воқии ин нам мебошад.</p>\n\n<h3>Фоидаҳои истифодаи наварии ғиринкӣ дар коркунии фенугрик</h3>\n<ul>\n<li><strong>Бозсавии об:</strong> Навари ғиринкӣ моро ба тозагони реша ба таври мустақим мерасонад ва аз буғи мустақим ва дарояш беҳадди чуқур пешгирӣ мекунад. Ин боиси он мегардад, ки маблағи назаррас аз захираҳои оби ширин ё саноатӣ боз дошта мешавад.</li>\n<li><strong>Якхунии рушд:</strong> Эҷоди доимии нори тарро ба рӯи баробари рузҳои ҷанобон ва осон кардани ҷамъоварии механизатсия мекунад. Ҷанобоне, ки дар муҳити тарри тағйирёбанда рузӣ мекунанд, аз ҷиҳати андоза ва потенсиали истеҳсолӣ низ нобаробарии бештар доранд.</li>\n<li><strong>Кам кардани чармакӣ:</strong> Бо марказгир кардани об дар норҳои зарра, рузии ашалеҳаҳо дар байни ҷузҳо кам мешавад. Ин масъала ба таври мустақим ба кам кардани ҳарҷаҳои пуршавии доруҳои химиявӣ ва коркарди тракторӣ дар миёнаи фавронӣ таъсир мерасонад.</li>\n<li><strong>Ҳалли таҳаввулоти намакӣ:</strong> Дар минтақаҳое, ки шорири хок баланд аст, шустани маҳлуди намакиро бо дақиқии бештар тавассути нори tip имконпазир аст, ки монеъи ҷамъшавии намак дар минтақаи реша мешавад.</li>\n</ul>\n\n<h2>Параметрҳои техникиӣ барои беҳтар кардани нори tip дар шабадилӣ</h2>\n<p>Барои расидан ба беҳтарин самаранокии кор, бояд аз норҳои tip-е истифода бурд, ки фосилаи мунтазам ва суръати хориҷ шудани об доранд. Одатан, фосилаи сӯрохиҳо барои партоби дони майда, ба монанди шабадилӣ, байни 10 то 15 сантиметр муайян карда мешавад. Агар шумо ба сифати бунёди баландтар ниёз дошта бошед, метавонед бо омӯзидан <a href="https://navar-abyari.ir/farq-nawwar-tip-bolal-dowkh-w-plaked/">Фарқи нори tip - бӯлуғ ва дуخت ва плак</a> Тафовурро дар устуворӣ ва пайдарии ҷараёни об байни ин ду намуди сархат дида бароед. Нуҳҳои плёнокӣ (беҳ) одатан ба муқовимати дарозмуддат ба гирифторӣ бештар ҳастанд ва барои парҳезҳои чандҳафтагӣ, ба монанди шибит, вариант беҳтар ба ҳисоб мераванд. Инчунин, ғафсии девори нуҳ бояд ба таври тӯлид шавад, ки ба фишори дохилии лӯла ва фишори механикии шиёш муқовимат кунад. Интихоби нуҳи тейби мувофиқ танҳо яке аз қисмҳои маводи баста мебошад; системаи филтратсия низ бояд дақиқан мувофиқ андозаи сӯрохҳо калибр карда шавад, то аз зарар расонидан ба системаи умуми пешгирӣ кунадад.</p>\n\n<h3>Таъсири амики хок ва навъи система ба самаранокӣ</h3>\n<p>Амелики рӯиши решаҳои шибит то 1 метр бароварда мешавад. Системаи нуҳи тейб бояд бо фишори мувофиқи хат (одатан 1 то 2 бар) кор кунад, то об ба таври хуб тақсим шавад. Дар муқоиса бо дигар парҳезҳо, <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%da%a9%d8%af%d9%88-%d8%a2%d8%ac%db%8c%d9%84%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосилоти кӯрда бо аҷил дар як гектар</a> Бо истифода аз нуҳи тейб низ шабоҳати зиёде дорад, аз ҷумла ниёз ба танзими дақиқи хароҷоти об барои пешгирии обгиршавии реша. Аммо, шибит ҳассосияти камтарро ба обгиршавии муваққатӣ нишон медиҳад, аммо ҳассосияти баланди ба хушкшавии зуд ваъд дорад. Бинобар ин, сикли обёрӣ бояд кӯтоҳ ва такрорӣ танзим шавад. Илова бар ин, намуди хок низ нақши назаррас дорад; дар хокҳои ришоданавар монанди лой, нуфузпазирӣ пасттар аст ва нуҳи тейб бо хароҷоти пасттар, вале мӯҳлати зиёдтар арзёбӣ аст. Дар хокҳои рӯйи, хароҷоти баланд барои пешгирии намоири амиқи об зарур аст. Бинобар ин, анҷом додани санҷишҳои нуфузпазирӣ пеш аз парҳез тавсия карда мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-شنبلیله-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت شنبلیله در هکتار با نوار تیپ - تصویر 1"/><figcaption>ҳосилоти парҳез дар як гектар обёрӣ тавассути нуҳи тейб шибит</figcaption></figure>\n\n\n<h2>Бароварди ҳаҷми ҳосилоти шибит дар як гектар бо нуҳи тейб</h2>\n<p>Бароварди дақиқи ҳосилот бе назардошти вазъиятҳои иқлимии маҳаллӣ мушкил аст, аммо додаҳои марзии нишон медиҳанд, ки бо истифодаи дуруст аз нуҳи тейб, метавон интизор шуд, ки <strong>Ҳаҷми ҳосилордони шаъбуни дар як гектар бо системаи навардори (narrow-web)</strong> то 15 то 25 фоиз зиёдатар аз усулҳои анъанавии оварии хуткӣ бошад. Ин зиёдшавии ҳосилордонӣ асосан ба сабаби истифодаи беҳтар аз чормағзҳои ҳалшаванда дар об (Fertigation) аст, ки бо системаи навардори (narrow-web) пешниҳод мешавад. Вақте ки об ва моддаҳои ғизоӣ ба таври дақиқ ба минтақаи реша мерасанд, ҷабби элементҳои минералӣ зиёд мешавад ва стресси растанӣ кам мешавад. Инчунин, камшавии хосилнокии аз сарфшавӣ ба воситаи намудашавӣ аз сабаби намҳои но мувофиқ саҳм дорад. Деҳқонон метавонанд бо сабти дақиқи истифодаи об ва муқоисаи он бо усулҳои дигар, сарфаи иқтисодии худро ҳисоб кунанд. Ин сарфакорҳо дар миқёси заминҳои бузург, метавонад тафовути муҳимро дар фоидаоварӣ ба вуҷуд орад.</p>\n\n<h3>Муқоиса бо парҳезҳои дигар</h3>\n<p>Барои фаҳмидани беҳтари мақоми шаъбуни, ба миқдори бодори кунҷит дар як гектар ва нуқтаҳои зиёд кардани ҳосилордонии он низ диққат кардан мумкин аст. Кунҷит низ як парҳези ороишӣ/дармонӣ аст, ки ба оварии қатрагӣ ҷавоби мусбат медиҳад. Фарқи асосӣ дар идоракунии оварии шаъбуни ниёз ба наварҳои тарҳ (Narrow Web) аст. Агар нақша барои истеҳсол ё хариди системаҳои пешрафта дошта бошед, <a href="https://navar-abyari.ir/narrow-web-tape-production-line-complete-guide/">Рӯйхатнамаи умумии хати истеҳсоли наварҳои тарҳ</a> маълумоти техникии дақиқ дар бораи сохтани ин маҳсулотро пешкаш мекунад, ки метавонад дар интихоби таъминкунандаи мувофиқ судбарад бошад. Ин рӯйхатнама масъалаҳое, ба монанди маводи асосӣ, техникаҳои пайвасткунии ва меъёрҳои сифатро фаро мегирад, ки барои деҳқонони харидорон низ хеле муҳим аст.</p>\n\n<h2>Нуқтаҳои амалӣ ва иҷроӣ барои деҳқонон</h2>\n<p>Иҷрои системаи навардори (narrow-web) дар заминҳои шаъбуни риояи чанд нуқтаи асосиро талаб мекунад. Агар ин масъалаҳо дар назар гирифта нашавад, ҳамаи сармоягузории ибтидоӣ беҳуда мешавад:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-شنبلیله-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت شنبلیله در هکتار با نوار تیپ - تصویر 2"/><figcaption>меҳвори ҳосилкории ҳасилии ҳектар, ороиши чучумӣ, кӯфас</figcaption></figure>\n\n<ol>\n<li><strong>Тасҳеҳи дурусти замин:</strong> Саҳҳи замин бояд пурра ҳамвор бошад, то ки фишори гидравликӣ барabar тақсим шавад. Ноустувории зиёда аз 2% метавонад дар қисмҳои поёнӣ фишори баланд ва дар қисмҳои болоӣ фишори пастро ба вуҷуд орад.</li>\n<li><strong>Сохтори хок:</strong> Дар хокҳои гилӣ, суръати баромадани об бояд камтар танзим карда шавад, то ҷамъ шудани об дар сатҳ пешгирӣ карда шавад. Дар хокҳои румолӣ, баръакс, овардани зиёдатир тавсия дода мешавад.</li>\n<li><strong>Паки кардани об:</strong> Асоси чучум хеле ҳассос ба хастанишавӣ бо заррачаҳои майда аст. Истифода аз тозакунии панҷраҳоӣ бо андозаи 100-200 микрометр зарур аст. Ҳамчунин, дар ҳолатҳое, ки аз чухунҳои намакнок истифода мебаранд, мавҷудияти чиншавии моддаҳои矿от хатари калон барои умри асос мебошад.</li>\n<li><strong>Муҳофизати физикӣ:</strong> Мишҳо ва ҳашароти зерзамина метавонанд ба навари кабуд зарар расонанд. Истифодаи муҳофизоти металлӣ ё лангари мучиб ба газ ва гардиш дар миқдоре метавонад аз ин мушкил пешгирӣ кунад.</li>\n</ol>\n<p>Инчунин, диққат ба тафсилоти пайваст намудани навари ба лӯлаи асосӣ муҳим аст. <a href="https://navar-abyari.ir/tol-fotuti-nori-tip-dar-kunor-dukhtashuda-va-ba-plastka/">Дарозии навари фотоэлектрики дар канҷори дӯхташуда бо пластик</a> (навари) метавонад дар давраи умри муфиди система нақш бозад; интихоби навари бо шӯрыҳои дӯхташуда ва пластиковӣ аз пардашудан ҳангоми ғаллафшонӣ пешгирӣ мекунад. Ин хусусият махсусан дар хокҳои ҳаҷумдор, ки ҷойгир кардани навари душвор аст, хеле муҳим аст.</p>\n\n<h2>Бахурӣ бештар (FAQ)</h2>\n<h3>Каҳ фавасоли барои навари кабуд дар шӯблилие тавсия мешавад?</h3>\n<p>Одатан фавасоли сутунҳо 40 то 50 сантиметр аст ва навари кабуд ақиқан дар ҷойи сутуни ғаллафшонӣ ҷойгир мешавад. Фавасоли сӯрохаҳо 10 то 15 сантиметр идеалӣ аст. Ин андозҳо вобаста ба намудҳои шӯблили ва шартҳои иқлимии минтақаи шумо танзим карда мешаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-شنبلیله-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت شنبلیله در هکتار با نوار تیپ - تصویر 3"/><figcaption>crop yield per hectare drip irrigation шӯблили</figcaption></figure>\n<h3>Оя нумонаи банди барои ҳамаи намудҳои шамолилия мувофиқ аст?</h3>\n<p>Бале, вале барои навъҳои дандонавӣ, ки дар барояшон намуди дандонавӣ муҳим аст, идоракунии охирини об (Cut-off) бояд дақиқтар бошад, то сифати дандонавӣ нигоҳ дошта шавад. Қатъи об дар вақти дуруст сахтӣ ва ранги дандонавиро беҳтар мекунад.</p>\n\n<h3>Фарқияти нумонаи банд бо тамғаи оддӣ чист?</h3>\n<p>Нумонаи банд як намунаи мусаллаҳ бо сӯрохҳои чандто аст, ки намунаи намнокандоҳиро месозад, дар ҳоле ки тамға давонони алоҳидаро дар масофаҳои муайян рехт мекунад. Нумонаи банд барои намоиши сатҳии шиққорчӯб монанди шамолилия якнамоӣ баландтарро месозад ва даромади ниҳоии он дар ҳар гектар одатан камтар аст.</p>\n\n<h2>Хулоса</h2>\n<p>Истифодаи нумонаи банд дар намоиши шамолилия як усули ҷавонбахш барои зиёд кардани <strong>миқдори фурӯшӣи шамолилия дар гектар бо нумонаи банд</strong> ва кам кардани ҳамаи ҳаҷми обнукриш. Бо интихоби намуди дурусти нумона (платка ё духташавӣ), тозакунии дақиқи об ва пур кардани дурусти, кишоварз метавонад аз самаранокӣи максимуми ин ҳеби давононавӣ манфиат расонад. Тамоми муттаҳид намешавад, ки пеш аз иҷро, бо мутахассиси об дароз намуд, ва намунаҳои озмоиши хурд-масштабро ба назар гиред, то беҳтарин танзимот барои шароити кӯппи худ ба даст оред. Ояндаи кишоварзии устувор ба истифодаи ҷавонбахш аз захираҳои маҳдуд вобаста аст ва нумонаи банд яке аз устухони ин тағйирот аст.','Ҳаҷми ҳосили фуфулики дар як гектар бо технологияи нури Tiph: Раҳнамои мукаммал барои зиёд кардани истеҳсошавӣ ва сарфаи об','Самеъи меҳрати шунбалиҷо дар ҳектар аз таъсири мустақими системаи обёрӣ вобаста аст. Истиноди аз нивои таъинӣ метавонад самаранокии истиноди аз обро болабарда ва самаранокии иловакунандаи ҳосилро беҳтар сохт. Дар ин мақола мо муфассалот ва техникавиро баррасӣ мекунем.','publish','closed','closed','hosili-fufuli-tiph-guaran',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
