INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Кашф кунед, ки чӣ тавр бо истифода аз навори тип метавонед самараноии ҳар гектарро баланд бардоред. Ин раҳнамои пурра ва амалӣ барои ҳар як кишоварз таҳия шудааст, то фаҳмад, ки чӣ тавр истеҳсолотро бешуборӣ карда, самараноии корро зиёд кардан мумкин аст.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
