INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Рӯҳнамуди тафсилотӣ дар бораи арзишҳои кӯролӣ ва таъмини салоти тӯк бо нақшаи тиби дар як гектар. Ин рӯҳнамуд барои деҳқонон ва таллофзорин муҳим аст.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
