INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Бақалағӣ яке аз сабзавотҳои ҳассос ба шароити иқлимӣ мебошад, ки идоракунии зараррасонҳо ва бемориҳои он ҳамеша чализерӣ барои деҳқонон буд. Дар солҳои охир, гузашт аз обёрӣи хундишунӣ ба усулҳои обёрӣи қатқатӣ ва широятии риккарт парадигми нав дар истеҳсоми бақалағӣ бо сифати баланд ба вуjud овардааст. Аммо бисёр истеҳсолкунандагон фикр мекунанд, ки танҳо усули обёриро тағйир додаанд ва ба андозаҳои гигиенӣ ин тағйирот иғтибот надиҳандан, ҳолки <strong>Зараррасонҳо ва бемориҳои бақалағӣ бо обёрӣи қатқатӣ</strong> таъмоли мураккабро ташкил медиҳанд, ки дарки он метавонад маблағҳои ифлосиновиёро ба миқдоори назаррас коҳиш диҳад. Обёрӣи қатқатӣ бо таъсиси минтақаҳои хушк ва намноки муталлиф, шароити муҳитиро барои қисмонҳои хокӣ ва ҳашароти саркаро тағйир медиҳад; бинобар ин деҳқон бояд стратегияи муборизаи худро бо ин воқеияти физикӣ мувофиқат диҳад.</p>\n\n<h2>Механизми идоракунии бевосита зараррасонҳо тавассути ислоҳи намнокӣи хок</h2>\n<p>Дар усулҳои анъанавӣ, намноки баланди сатҳӣ дар тамоми масоҳати майдони зиракшавӣ, заминаи муносиби барои истеҳсоми хӯрдуҳои кӯрпакҳои хурду ва баъзе зараррасонҳои хокӣ фароҳам меорад. Бо гузоштани системаҳои нав, намнокӣ асосан дар рикки тӯҳт чашмчаи обёрӣ ё қатрадор мутамарказ мешавад. Ин паҳношавӣ, минтақаҳои хушки байни сатҳҳоро ба вузуд меорад, ки аз интиқоли механикии баъзе патогенҳо пешгирӣ мекунад. Аммо лозим аст бидонем, ки мавҷҳои қисмонӣ дар широяти риккарт метавонад дар сурати набудани мувознати обвааимо, баъзан аз пешбиниҳо шиддаттар зоҳир шавад. Вақте ки реша дар шиддати обӣ нест, растанӣ муқовиматандар ба стрессаи физиологӣ аст ва баъд аз ин, зараррасонҳо аз ҷумла зангҳо ва моҳигиҳо камтар ба он ҳамла мекунанд. Идоракунии намнокӣ дар ин асос бояд ҷойи оинҳои доимиро иваз кунад ва вобаста ба ҳолати рушди бақалағӣ танзим шавад, то аз шакли гиёҳҳои зараровар дар тӯли роҳҳо пешгирӣ шавад; зеро ин гиёҳҳо сохтори асосии кӯрпакҳои хурду мебошанд.</p>\n\n\n\n<h2>Бемориҳои қисмонӣ ва идоракунии онҳо дар фазои банд</h2>\n<p>Муҳимтарин зараррасонҳо ва бемориҳои бамия дар маҷориаи нафис (дроп) боши барои бемории зинги бамия ва шалгум-саф (каф) мебошад. Дар фазои баста ба монанди хонаи шабакадор, суғори нафис бо кам кардани намии ҳавои маҳаллӣ дар атрофи баргҳо шароитро барои ҳосилшавии спорҳо-и заминӣ ва зангулҳои пудрашудар душвартар мекунад. Идоракунии ин қисм ба эҳтиёти махусо ниёз дорад. Бояд эҳтиёт шуд, ки хулосаи парокандашавии ҳосил дар рӯйи парда аз пеш хуб муайян шуда бошад, то намӣ аз сатҳи хок ба самти поён ҳавассаҳо равона шавад. Ҳамчунин, истифодаи рӯйи парда боиси инъикоси воқеии минтақаи қариб кардани реша мебошад; бинобар ин, агар бемории зинги бамия эҳтимол шавад, метавон минтақаи сироятшударо бо эҳтимали тез аз дигар қисмҳои боғ ҷудо кард. Таъмини сардгардонӣ бо истифода аз оби гармшуда дар системаи нафис, усули иловагӣ мебошад, ки дар шартҳои муайян тавсия дода мешавад.</p>\n\n<h3>Барҳам задани зараррасонҳои хурди писто-ншинӣ</h3>\n<p>Ҷойгиршавии зонаҳои хушк дар атрофи қаторҳои бамия зараррасони сахторо ба дарундодии сабагҳо ва баргҳои дохилӣ мефиристад ва дастрасии ба онҳоро душвартар менамояд. Дар ин ҷо нақши назорати бунёдӣ хеле муҳим аст. Яке назари умумӣ барои пешгирии зараррасонҳо дар рӯйи парда бояд баррасии ҳафтагии пардаҳои баргашударо дар бар гирифта бошад. Дар фазои ошкор, истифодаи чӯбҳои часпандаи зарда ва ҷойгир намудани онҳо дар тӯли рӯй парда, оғури гӯйивии ғайрисимикӣ мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-بامیه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های بامیه با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation бамия</figcaption></figure>\n\n<h2>Нақси сифати об дар пешгирии зарардиҳии решаҳо</h2>\n<p>Яке аз хатогиҳои маъмул, ки боиси эҳтироми <strong>Зараррасонҳо ва бемориҳои бамия бо суғории нафис (дроп)</strong> яст, ки фаҳиши сифати обро аз назар доранд. Обҳо, ки бо бактерияҳои бардоши капираи чиллоғ осеб мебинанд, агар аз сефтонҳои стандартӣ гузаранд, бевосита бактерияҳоро ба минтақаи реша мерасонанд. Дар системаҳои қатқатӣ решаҳо дар фазои хеле маҳдуд дар хок ҷойгиранд; бинобар ин ҳар гуна осеббохӣ бо суръат ба тамоми раста мерасад. Аз ин сабаб, истифодаи филтрҳои скрини сеттӣ ва намунаи 150 микрон зарурати муҳим аст. Инчунин, агар аз манбағҳои обҳои сатҳӣ истифода баред, назорати кимиёвии об барои пешгирии ҷамъшавии калсий ва намакҳо лозим аст. Ин ҷамъшавӣ ҳам сабаби халали наздикии чиллоғ шуда, ҳам намии ноамонро ба реша мерасонад.</p>\n\n\n\n<h2>Барномаи амалӣ: нақшагирии парвариш ва назорат</h2>\n<p>Истифодаи наздикии чиллоғ имкон медиҳад, ки аз парвариши чангӣ чиллоғ бо меҳваҳои хурди дигар истифода кунем. Қариб аст, ки дарёфтан, ки нишу кардани салерӯи чиллоғ низ яке аз роҳҳои пазирёфта барои ба даст овардани меҳваи иловагӣ аст. Дар ин усул растаҳои кӯтоҳ дар наздикҳои хушк рӯӣ меёбанд ва харакундаҳои пшики хушкро ҷалб мекунанд, ки бо чиллоғ робита доранд. Ин намуди парвариши чангӣ гуногунии биологиро зиёд мекунад ва бо оқибат, зарароварон ва бемориҳои чиллоғ бо обёрӣ дар қатқат кам мешаванд. Дар амал, деҳқон бояд назорати худро дар баргирии намуди барг дар соатҳои субҳ марказӣ гардонад. Дар ҳолати дида шудани дарагҳои зард, бояд аз фосилаи муносиб ва сояи бафташуда истифода бурд, то мувозинати намуди ҳаво то охири давраи ривҷот нигоҳ дошта шавад.</p>\n\n<h3>Нуқтаҳои асосӣ барои коҳиши истифодаи доруҳои кимиёвӣ</h3>\n<ol>\n<li><strong>Назорати реша:</strong> Ҳар ду ҳафта як, наздикии оборишавиро барои дида шудани дарагҳои қабурнӣ (бемории камарбанди қабурнӣ) санҷед.</li>\n<li><strong>Идоракунии намии нисбатӣ:</strong> Дар ҳавокашониҳо, намии нисбатӣ бошад, дар дарёи беоамон аз 70 фоиз камтар нигоҳ дошта шавад.</li>\n<li><strong>Истифодаи обистоди:</strong> Пеш аз воридшавии об ба навар, барои кам кардани занбохтори зараровар гармиёти тақрибан 40 дараҷаро истифода баред.</li>\n<li><strong>Гуногунии ғунукдорӣ:</strong> Аз даври ғунукдорӣ бо маҳсулоти дигар, ба монанди картошка ё сабзавоти монанд барояш хориҷ шавед, то беморӣбахшандаҳо нест шаванд.</li>\n<li><strong>Пайдо ба баробари ғунукдорӣ:</strong> Оборирӣ по қатроиро дар миёнаи шаб анҷом надиҳед; ин кор боиси ҷамъ омадани тамоми реша ва шикастани зангони кӯтуб мебошад.</li>\n</ol>\n\n\n\n<h2>Саволҳои такроршуда дар бораи зарароварон ва бемориҳои кӯтуб бо обирони по қатрагӣ</h2>\n<p><strong>Оё истифода аз навар кӯтуб боиси афзоиши комарони хокӣ мегардад?</strong> Не, воқеа шубори хушкаши атрофи рафъ, ҳолатро барои лулҳои пашмагон коҳиш медиҳад. Ҳамон сурате, ки шумораи зиёдро мушоҳида кунед, истифодаи кӯдаҳои фоидаманди заминӣ ё истиғамӣ дар ороиш дахлдор метавонад даъм диҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-بامیه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های بامیه با آبیاری قطره‌ای - تصویر 2"/><figcaption>Асоби ва бемории паразити ашкор, обгирии қатрагӣ, бамие</figcaption></figure>\n<p><strong>Беҳтарин роҳи шиносоии бемории банди поёнӣ барои бамие чӣ аст?</strong> Бемории банди поёнӣ дар бамие аз роҳи намдори поёнӣ аз доираҳои поёнии барг ташкил меёбад. Дар системаи қатрагӣ, вобаста ба роҳбарии решаи дар амиқ ба об, баргҳои поёнӣ хушкро нишон медиҳанд; вале агар аз обгармии гарм истифода шавад, хатарнокӣ бемории бактериявӣ кам мешавад.</p>\n<p><strong>Оё фавсатгузории рафъи кучук ба шиддати паразити пароканди барг таъсир мерасонад?</strong> Бале. Фавсати зиёд боиси коҳишди ҳаҷми замини ҷаббиш ва фишори решагӣ, ки ба оқибпарҳезии паразити пароканд сурат мегирад. Фавсати стандартӣ рафъи кучук бамие бояд бо назардошти шароити замин ҳисоб шуда шавад.</p>\n<p><strong>Оё имкон дорад аз таъминоти кӯдашаклӣ дар давраи ҳассосияти бамие ба паразит истифода бурдан мумкин бошад?</strong> Не, таъминоти иловагии кӯдашаклӣ боиси заифӣ дар бофетиш ва зудтарин ҷаббиш паразитро мекунад. Ҳамон сурате, ки истифодаи пудрави фосфатӣ барои баландбардошти бофетиш тавсия карда мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-بامیه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های بامیه با آبیاری قطره‌ای - تصویر 3"/><figcaption>заҳароварии кабудӣ, бемориҳо, обёробии тақтирӣ Бамия</figcaption></figure>\n<p><strong>Маслиҳати охирин чӣ мешавад?</strong> Дар симои мушоҳидаи сӯзонӣ ё дағалҳои хурд, пеш аз гузоштани табдили заҳар, аз маслиҳатҳои ҳалҳои муҳаррики барои <a href="https://navar-abyari.ir/peanut-seed-rate-per-hectaramm-arabica-factors/" target="_blank">Аннодӣ, вазъи дунё</a> Боварӣ ҳосил кунед, ки зичии майдон мувофиқ бошад; зеро зичии зиёд, боиси пайдоиши баъди зараррасонӣ ба тамоми майдон мешавад.</p>\n\n<h2>Хулоса</h2>\n<p>Идоракунии заҳараварӣ ва бемориҳои кабудӣ бо обёробии тақтирӣ, роҳи пурраи нигарӣ аст, ки омехтае аз технологияҳои идоракунии обёробӣ, назорати биологӣ ва идоракунии намии ҳаворо дар бар мегирад. Ин усул на танҳо боиси камшавии баҳоии истифодаи об ва паст шудани хароҷоти заҳарравӣ мебошад, балки маҳсулоти дорои нигоҳдории дуртар ва сифати стандартии баландтарро ба истеъмолкор мерасонад. Бо назардошти ҳамаи ҷанбаҳо, аз муайянкунии зомонавӣ паразитҳо то истифода аз асборҳои кӯмаккунанда монанд намудиқкунандаҳо ва тавуқҳои часпак, метавонем самаранокӣро дар сатҳи баландтар нигоҳ дорем. Дар охир, муваффақият дар ин соҳа ниёз ба диққати махсус ба сифати об, танзими дақиқи нӯри таҳтирӣ ва назорати давомии ҳолати решаҳо ва баргҳои поёнӣ дорад.</p>\n<p><strong>Маводи вобаста:</strong> <a href="https://navar-abyari.ir/%D9%86%DA%A9%D8%A7%D8%AA-%D9%85%D9%87%D9%85-%D8%AF%D8%B1-%D9%87%D9%86%DA%AF%D8%A7%D9%85-%D8%A7%D8%B3%D8%AA%D9%81%D8%A7%D8%AF%D9%87-%D8%A7%D8%B2-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D8%A2%D8%A8/">D986DAA9D8A7D8AA D985D987D985 D8AFD8B1 D987D986DAAFD8A7D985 D8A7D8B3D8AAD981D8A7D8AFD987 D8A7D8B2 D986D988D8A7D8B1 D8AADB8CD9BE D8A2D8A8</a>, <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%86%D8%BA%D9%86%D8%AF%D8%B1-%D9%82%D9%86%D8%AF-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA DA86D8BAD986D8AFD8B1 D982D986D8AF D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%b4%d9%84%d8%ba%d9%85/">Роҳнамои ҷамъбасти истифодаи пайчҳои репах: масофаҳо, мувофиқатҳо ва нуқтаҳои асосӣ</a></p>','Заҳар ва бемориҳои бамиҳе дар системии обёрӣсози қатрагӣ ва нурониш: Раҳнамои амалӣ','Ориғосии қатқата танҳо барои бозгашти об нест, балки калид дар идоракунии зарароварон ва бемориҳои сабззори чорводорӣ мебошад. Дар ин мақола муайян менамоем, ки чӣ гуна бо назорати дақиқ рӯшноӣ, аз паҳншавии суръи пӯлод, тӯри қаҳраӣ ва хурдумҳо пешгирӣ кунем.','publish','closed','closed','zahar-va-bemorihoyi-bamihe-sistemiyi-obor-suzi-qatragi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
