INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Ҷӯроф-и сабз яке аз асосҳои асосии чарои чорводорӣ ва инчунин маҳсулоти монанди дони ҷӯроф аст, ки дар бозорҳои ҷаҳонӣ ва дохилӣ мавқеи махсус дорад. Кирдорон ҳамеша бо мушкили танзими <strong>миqdори дони ҷӯроф дар гектар</strong> муофиқ мебошанд, зеро ғарриши зиёд аз ҳад зарурати дони на танҳо ҳарамкуш аст, балки сабаби рақобат байни наботот ва паст кардани сифати дони ва ғалема мегардад. Дар муқобил, ғарриши кам аз ҳад муқаррарӣ низ боиси паст шудани зичии чарогӣ ва хирашпазирии зиёдтар нисбат ба олакҳои зараровар мегардад.</p>\n<h2>Таъсири системаи нӯбар тиби ба зичии ғарриши ҷӯроф</h2>\n<p>Истифодаи системаҳои обёрӣ понақуш ва нӯбар тиби роҳи ғарришро дигаргун мекунад. Дар ин роҳ, решаҳо ва фазои байни кушоҳҳо бо нӯбар обёрӣ даврагӣ пур мешаванд, ки боиси истифодаи беҳтарини нам ва моддаҳои ғизоӣ мегардад. Барои ҳамин, вақте ки аз баланд шудани самаранокии нӯбар тиби истифода мебаред, метавонед аз ҳаҷми ҳамон об ҳаҷми бештари решаҳоро фаъол нигоҳ доред. Ин хусусият ба кирдорон имкон медиҳад, ки бо нигоҳ доштани ҳаҷми муаййани дони дар гектар, масофат байни қаторҳоро бо диққати бештар танзим кунанд, то ки наботот дар қимматтарин парҳез ва дигаргуншавӣ (Kumarshidagi) камтар бошад.</p>\n\n<h2>Миқдори беҳтарин дони асосан шароитҳои иқлимии ва дони</h2>\n<p>Адади сахт барои <strong>Миқдори дони ҷӯроф дар гектар</strong> Он ҳолат вуҷуд надорад, ки барои тамоми Эрон умумисанҷиш карда шавад, зеро иқлими хушки ҷанубӣ бо иқлими мулоими шимолӣ фарқҳои асосӣ дорад. Дар ҳоли умумӣ, миқдори тавсияшуда барои дониҳои стандартӣ (ниҳоди тоза зиёда аз 90% ва қудрати бароридан зиёда аз 70%) одатан байни 15 то 25 килограмм дар гектар мебошад. Аммо, ин вайрон ба таъсири омили зерин мутақобил аст:</p>\n<ul>\n<li><strong>Навъи ниҳод:</strong> Ниҳодиҳои хушдилкор ва ба хушкӣ тобовар ба зичии камтар ниёз доранд.</li>\n<li><strong>Шартҳои замин:</strong> Дар заминҳои шаброки сабук, барои пешгирии парокандашавии растаниҳо, вақте-вақте аз миқдори баланд (тақрибан 25 килограмм) истифода мешавад, то пӯшиши барвақт ба вуҷуд ояд.</li>\n<li><strong>Ҳади киш:</strong> Агар ҳади асосии киш ғизои чорӣ бошад, фориғаи сатҳҳо бояд наздиктар бошад ва дар натиҷа миқдори ниҳод дар гектар баланд мешавад.</li>\n</ul>\n<p>Барои интихоби дақиқтар, омӯзиши миқдори ҳосилоти хоби офтобгардон дар гектар ҳамчун истиноди муқоисаӣ метавонад муфид набошад, аммо мантиқи муайян кардани коэффисиенти табдили ниҳод бар асоси иқлим истифодашаванда аст. Олмоҳ растании аст, ки дар ҳарорати мулоим беҳтар рушд мекунад, бинобар ин дар минтақаҳои сармоян, вақти киш таъсири бештар ба дараҷаи зиндамонӣ ва дар натиҷа миқдори ниҳоии ниҳоди кишшаванда дорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-یونجه-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر یونجه در هکتار: راهنمای جامع - تصویر 1"/><figcaption>normi bobi bar soni chumish yoncha</figcaption></figure>\n<h3>Nuqushai kalon dar kharid va intikhabi bob</h3>\n<p>Yeki az muhimtarin omilho dar te\'dinin <strong>miqdori bobi yoncha dar soni chumish</strong>Kifoyati bob ast. Pesh az kharid, hojat bobi baal karda. Muzodi pok, muzodi nu\'mudon va muzodi osimonbudi bob boyaad dar standardhoi melli (modda 1280) bovad. Istifoda az bobhoi kamshuda yoki qadimii mumkun ast sabobiaad, ki shomo majbur shoed miqdori ziyataro soni chumish korod, to ki kamkuni burkhami tarro va nu\'mudon ro jibor konad. Hamchinon, bobhoi tahsili az markazhoi tadqiqotki kishovorodi ahmi odatan surati balatari dorad va mumkun ast, ba dozhoi kam to moddai mutolub rasonad.</p>\n\n<h2>Karbudi navi teip va masofai karshi yoncha</h2>\n<p>Intikhoi masofai satri ba satri parametri digar ast, ki mustaqimam ba <strong>miqdori bobi yoncha dar soni chumish</strong> タасир мерсонидаш мекунад. Барои истифодаи лентаи чизишкунӣ, системаи обёрӣ бояд ба таври чунин ҷойгир карда шавад, ки ҷараёни об бевосита ба решаҳои наъф расад. Масофаи стандартии лента чизишкунӣ барои наъф одатан байни 50 то 60 сантиметр дар шартҳои умумӣ аст. Бо наздик шудани лента, бояд миқдори бубро дар воҳиди дарозии сафҳ каҳиш диҳед, то зичии ниҳоӣ дар гектар аз ҳадди иҷозат гузаранда нашаванд.</p>\n<p>Ашноӣ бозар аз бенафиъҳои ин система имкон медиҳад, ки шумо аз хароҷотҳои зарурнокии ҳисоб карда шаванд. Шумо метавонед мақола <a href="https://navar-abyari.ir/foydahoi-nvori-tipii-obyri-tarafduzi/">Бенафиъҳои лантан чизишкунӣ</a> -ро хонед, то донед, ки чӣ гуна ин технология, талаботи идоракунии дақиқтарро дар парвариши кӯдак дорад. Дар системаи анъанавии чизишкунӣ, шумо манбаи нуқтагии обро доред, аммо дар лентаи чизишкунӣ, тамоми паҳӯи пӯшида дар таъсири обёрӣ қарор мегирад, ки ин ба якхеллашуди парвариш дар сафҳҳои ҳамсоя мусоидат мекунад.</p>\n<h3>Роҳнамуди ғайрихашкӣ дар хокҳои гуногун</h3>\n<p>Ҳар гуна тағйирот дар заминаи парвариш, ниёз ба муайян кардани дубораи <strong>миқдори буби наъф дар гектар</strong> дорад. Барои нақшарезии амалӣ, дар назар гиред:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-یونجه-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر یونجه در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Самон бародак бар гектар ҷӯранг</figcaption></figure>\n<ol>\n<li><strong>Обҳои сабук (решишӣ):</strong> Қобилияти нигоҳдории об паст аст. Барои сохтори зудро ҷойгир кардан ва пешгирии хӯрокӣ, миқдори бародакро ба самаранокӣ (25 килограмм) танзим кунед.</li>\n<li><strong>Обҳои вазнин (гилӣ):</strong> Паст будани тақсимоти унсурҳо метавонад ҷинс кардани бародакро роҳ дода надиҳад. Беҳтар аст, ки миқдори бародак миёна (15 то 18 килограмм) нигоҳ доред ва бародакро каме чуқур ҷинс кунед, то ба намӣ дар чуқурӣ дастрасӣ пайдо кунад.</li>\n<li><strong>Сатҳи ҷойгиршавии нави ғазв:</strong> Бояд бародакро дақиқан рӯи нави ғазв ё бо масофаи 5 то 10 сантиметр аз он ҷинс кунед, то ки тамоси мустақими унсурҳо бо об вуҷуд дошта бошад.</li>\n</ol>\n\n<h2>Ҷавоб ба саволҳои маъмул</h2>\n<h3>1. Оё ягонороғро мебошад, ки ниҳоли чанакӣро охири тирамоҳ кунем?</h3>\n<p>Бале, вале миқдори бунҷид бояд бо таваҷҷуҳ интихоб шавад. Таҳаммул дар ҳолати паҳлӯйии паст боиси камшавии суръати пайшодан мегардад. беҳтар аст, ки аз бунҷидҳои баландсатҳ ва иловагӣ истифода баред, то дар шароити хунук низ рӯшди қобили қабул дошта бошанд ва миқдори бунҷид дар 1 гектарро каме камтар аз ҳолати баҳорӣ танзим кунед, то ки ба гиёҳ фурсати кофӣ барои гузоштан дар давоми фаъолияти исқотӣ бошад.</p>\n<h3>2. Қисми кадоме аз риштаи чанакӣ барои ниҳол кардани чанакӣ муносибтар аст?</h3>\n<p>Одатан тавсия мекунад, ки бунҷидро каме аз маркази ришта дур ниҳол кунед (тақрибан 10-15 см аз ришта). Агар бунҷид дақиқан рӯи ришта қарор гирад, дар сурати номувозифа будани пуркунанда ё афзудани фишори об дар оғози фасл хушкшавии решаҳо вуҷуд дорад. Инчунин, масоҳат байни ду сатри чанакӣ бояд бо масоҳат байни ду риштаи чанакӣ мувофиқ бошад, то идоракунии зарарнокҳо осонтар шавад.</p>\n<h3>3. Тафовути ниҳол кардани чанакӣ бо оғъоф дар истифодаи об ва бунҷид чӣ қадар аст?</h3>\n<p>Ҳатто агар навъҳои гуногун бошанд, дарки робитаи зичии бунҷид бо об кӯмакрасон аст. Барои муқоисаи тезтар ба... <a href="https://navar-abyari.ir/tikmi-kunjat-dar-hektar/">миқдори бунҷиди оғъоф дар гектар...</a> диққат диҳед. Оғъоф аз сабаби таҳаммул ба хушкӣ, одатан бо зичии бунҷиди камтар ва масоҳати сатри васеътар кунда мешавад, дар ҳоле ки чанакӣ ҳамчун гиёҳи бисёрсолаи орағӣ ба зичии баландтар барои нигоҳ доштани пӯшиш ва рақобат бо зарарнокҳо ниёз дорад.</p>\n<h3>4. Агар масофаи нӯҳурип аз 60 то 80 сантиметр зиёд шавад, чӣ рӯй медиҳад?</h3>\n<p>Зиёд кардани масофаи нӯҳурип барои ёнҷа бехатарии ғолиби шиддатиро ба вуҷӯ меорад. Агар мехоҳед масофаи нӯҳоро зиёд кунед, бояд миқдори боби ёнҷаро дар ҳектарро зиёд кунед, то ки партаби бунгари зичтар ба решаҳои зиёд ва қобилияти бештари ҷазби об аз макони васеъшуда кӯмак расонад. Дар аксари ҳолатҳо, бунгаринон заиф мешаванд ва ба бемориҳои решаҳо ҳассос мегарданд. Инчунин омӯзиши масофаи нӯҳурип дар Чин метавонад нумунав барои фаҳмидани таъсироти минтақаҳои марзи оборӣ дар каророти зич бошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-یونجه-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر یونجه در هکتار: راهنمای جامع - تصویر 3"/><figcaption>normai bobo yek haqare fano ёнҷа</figcaption></figure>\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Ёфтани мувозинат байни самаранокии максималӣ ва хароҷоти камтарин калиди муваффақият дар корҳои ёнҷа аст. <strong>Миқдори боби ёнҷа дар ҳектар</strong> Набовад чун як рақами собит ба назар гиред; балки бояд бо назардошти намуди бобӣ, амики каротӣ, масофаи нӯҳурип ва шароити иқлимии маҳаллӣ ҳисоб карда шавад. Якҷоя кардани боби сифатнок бо нақшаи дақиқи оборӣ тавассути нӯҳурип ба шумо имконият медиҳад, ки солҳои баъд аз карот низ самаранокии устувор ва баландро эҳсос кунед.</p>\n<p>Инчунин пеш аз сармоягузорӣ ба нӯҳҳои оборӣ, ҳатман мушаххасотии техникӣ дороро санҷед. Омӯзиш <a href="https://navar-abyari.ir/tips-before-buying-irrigation-drip-tape/">Нимҳозорҳо пеш аз хариши рӯйпӯшҳои оромулӣ (тип)</a> Метавонад аз хариши рӯйпӯшҳои сифати нопурра, ки боиси омадани об ва ҳалокати растаниҳои чӯб (йунҷа) дар ҳафтаҳои аввал мегарданд, пешгирӣ кунад. Дар хотир нигоҳ доштан: назорати дақиқи поёни растаниҳо дар оғози фасли катин беҳтарин роҳнамо барои муайян кардани миқдори бӯнбадҳо дар солҳои оянда мебошад. Бо риояи ин принсипҳо, метавонед майдонҳои чӯбӣ (йунҷа)-и худро ба фазои сояванд ва камхарҷ табдил диҳед.</p>\n<p><strong>Маводу алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%86%d8%ad%d9%88%d9%87-%d8%a7%d9%81%d8%b2%d8%a7%db%8c%d8%b4-%da%a9%d8%a7%d8%b1%d8%a7%db%8c%db%8c-%d9%88-%d8%a8%d9%87%d8%b1%d9%87%d9%88%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c/">Роҳ ба афзоиши самаранокӣ ва фоидабарории рӯйпӯшҳои оромулӣ (тип)</a></p>','Миқдори тоҷи нафуд дар гектар: Роводнамои пурра','Ючора чун яке аз муҳимтарин растаниҳои донадор ва чароӣ, ба идоракунии дақиқ дар марҳилаи кардан ниёз дорад. Дар ин мақола мо миқдори оптималии бехи ючора дар гектарро бо назардошти шартҳои иқлимӣ ва системаи обёрӣ тавассути монотонӣ ва навар тибро баррасӣ мекунем. Аз интихоби бехи стандартӣ то масофаи амалиёти кортӣ ва идоракунии рушд, дастураҳои комил барои деҳқонони арҷманд пешбинӣ шудааст. Бо пайравӣ ба ин нуқтаҳо, шумо метавонед ҳамзамон бо кам кардан хароҷотҳо, ба баландтарин дараҷаи устуворӣ ва сифати растаноӣ расед.','publish','closed','closed','miqdori-toji-naftud',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
