INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин роводнамои пурра ошён мекунед, ки чӣ тавр миқдори тоҷи нафудро дар ҳар як гектар дуруст муайян карданӣ. Маслиҳатҳои техникӣ ва амалӣ барои деҳқонони тоҷик.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
