INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','Миқдори бехунии маш дар гектар: Раҳномии кишоварзӣ бо обёрӣи қатрагӣ' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Донистани миқдори дурусти бехунии маш дар як гектар барои фермерҳои тоҷик. Таҳлили пурра оид ба техникаҳои обёрӣи қатрагӣ ва навартии типӣ (nobar type). Ҷавоб ба саволҳои амалӣ дар бораи ҳаҷми бехунӣ.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
