INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Броколи (<em>Asparagus officinalis</em>) як яке аз растаниҳои даимоӣ ва иқтисодӣ мебошад, ки дар боғҳо ва ҳазинаҳои Ҷануби Шарқӣ ва Эрон ғановат мешавад. Ин растани бо сабаби ниёзмандӣ ба шароити махсус дар давраи ҷавонӣ ва инкишофи ибтидоӣ, ба идоракунии дақиқи захираҳои оби ва моддаҳои кӯдаки ҳосилнок мебошад. Дар солҳои охир, истифодаи системаҳои <a href="https://navar-abyari.ir/potato-drip-tape-complete-guide/" target="_blank" rel="noopener">обории қатра-қатраву навиши типӣ</a> дар ғановати растаниҳои дарахтӣ, диққати деҳқонононро ба худ кашидааст. Гарчанде ки ин системаҳо асосан барои сабзиёти солона, ба монанди сабзӣ-заминӣ шинохта шудаанд, вале принсипҳои онҳо барои беҳтар кардани обори брокколи, бигзор дар марҳилаи муқаррарияти ибтидоӣ, истеъмол мумкин аст.</p>\n<p>Дар ин мақолаи воҳид, мо ба таҳқиқи ҷузъиёти техникии ғанолати брокколи, бо таваҷҷуҳ ба обори қатра-қатраву навиши типӣ парешур карда ҳастем. Аз интихоби навъи навиши типӣ ва муайян кардани фавқудураҳои ганолати то барномагузории дақиқи миқдор ва вақти обори, ҳамаи нуқтаҳои калидиро пурра мундариҷа мегиранд. Мақсади мо ин аст, ки деҳқон бо истифодаи захираҳои муқаррарӣ, стресс-и дарахти растаниро кам кунад ва дар натиҷа ба ҳосилнокӣ маълул даст ёбад.</p>\n\n<div class="image-container" id="image-1"></div>\n\n<h2>Морихҳи ғанолати брокколи: муҳимии интихоби бобу омода кардани замин</h2>\n<h3>Интихоби шамола ё ғулҳаи мувофиқ</h3>\n<p>Сифати ниҳоии маҳсулот-и брокколи бевосита ба саломатӣ ва сифати боб (ё ғулҳаи дарахтӣ) вобаста аст. Дар деҳқонии муосир, истифодаи бобҳои тасдиқшуда ва муқовимат-ба беморҳои зинҷову вирусӣ зарур аст. Баҳуди хариди боб, ба боберо таваҷҷуҳ кунед, ки эҳтимол-то ба дарҷабаанди баланд (Vigor) дошта бошад ва аз ҷиҳати техникаӣ беҳтар карда шуда бошад. Барои ғанолат дар қиммати баъдаи тиҷоратӣ, шиносӣ бо нисби ғанолати намуди дигери ҷў ва ҳулаватҳо метавонад дар баҳодиҳии миқдори истифодаи захираҳои иловагӣ кӯмак расонад; барои намуна, дарки умумӣ аз <a href="https://navar-abyari.ir/fava-bean-seed-rate-per-hectar-yield-factors/" target="_blank" rel="noopener">Маводи кишокӣ ва омилҳое, ки ба андозаи ҳосили лобия таъсир мерасонанд</a> Он метавонад принсипҳои монандро дар идоракунии зичии кундуни барқуқ истифода барад.</p>\n<h3>Омодакунии асоси кундун</h3>\n<p>Барқуқ ба хок сабук, бо дренаж ва бойи моддаҳои озоргаро ниёз дорад. Пеш аз кундун, хок бояд хуб шуд ва бошад. Сохтани шӯроҳои чуқур барои кундуну рудҳо, ҳавокунӣи решаҳоро беҳтар мекунад ва аз гирефтани решаҳо ба сбаби ҷамъ шудани об пешгирӣ мекунад. Агар аз системаҳои обёрӣи бо фишор истифода баред, ҳарифии дақиқи майдонҳо хеле муҳим аст, то аз ҷамъ шудани об дар нуқтаҳои поёнтар пешгирӣ шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-مارچوبه-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت مارچوبه با آبیاری قطره‌ای - تصویر 1"/><figcaption>methods of planting drip crop irrigation schedule барқуқ</figcaption></figure>\n\n<h2>Системаҳои обёрӣ: интихоби байни қатрагонӣ ва навоҳи тира</h2>\n<h3>Фоидаҳои обёрӣ бо қатрагонӣ барои барқуқ</h3>\n<p>Системаи обёрӣ бо қатрагонӣ, ба сабаби тақсимоти дақиқи об ва моддаҳои мазмуннок дар атрофи решаҳо, яке аз мувофиқтарин роҳҳо барои ин бутавар аст. Ин усул боиси ин менавишад, ки ноҳияи реша ҳамеша тар боқӣ монад, бе он ки асоси кундун дар об гушазад, ки ин барои решаҳои ҳасоси барқуқ муҳим аст. Дар муқоиса бо обёрӣ дар хок, системаи қатрагонӣ метавонад 30 то 40 дарсадро дар истифодаи об сарфа кунад. Ғайр аз ин, имконияти анҷом <a href="https://navar-abyari.ir/navori-tamp-baroi-lubiyo-rahnomai-ob-yori-qatreyi/" target="_blank" rel="noopener">Лентҳои тиббӣ барои нӯрӯн ва роҳнамоии обёрӣи қатқат</a> Мавҷуданд, ки нишон медиҳанд принсипҳои монанд барои дигар гиёҳҳои решадор ва сабзавот низ татбиқ кардан мумкин аст.</p>\n<h3>Ҷорӣ намудани лентҳои тиббӣ дар парвариши маржорӯн</h3>\n<p>Лентҳои тиббӣ ё Drip Tape ба сабаби насби тезуарзона ва хароҷоти камтар нисбат ба хатиқатҳои доимӣ, варианти бештар дилхоҳ барои марҳилаи аввали кишвортонӣ мебошад. Дар вақти насби лентҳои тиббӣ бояд боварӣ ҳосил кунед, ки фосила байни лента ва қатори кишоварӣ беопасон аст (одатан 15 то 20 сентиметр аз решаи асосӣ). Лентҳои тиббӣ бояд равшан ва якхела бар замин кашида шаванд, то ки тақсимоти баробар об таъмин шавад. Нуқтаи муҳим, фишори кории мувофиқ аст; лентҳои тиббии стандартӣ одатан бо фишори 1 то 2 бар кор мекунанд. Барои омӯзиши бештар дар бораи тарҳи беҳтарин лентҳо, шумо метавонед ба <a href="https://navar-abyari.ir/nori-tipa-kalmos-robnameyi-obyorii/" target="_blank" rel="noopener">Лентҳои тиббӣ барои сабзӣ ва роҳнамоии обёрӣ</a> ишора кунед, ки принсипҳои механикии монанд дорад.</p>\n\n<div class="image-container" id="image-2"></div>\n\n<h2>Ҷадвали вақтҳои обёрӣ: калиди афзоиши якхела</h2>\n<h3>Брамбарномаи обёрӣ дар марҳилаи муқарраршавӣ</h3>\n<p>Давраи 3 то 6 моҳи аввали баъд аз паҳн кардани бӯнҳо барои пиёз ҳисс-хавфтарин давра аст. Дар ин марҳила, растакҳо дар ҳақиқат тарокиши реша сохта истода, ба оби доимӣ ниёз доранд. Тавсия мекунад, ки обёрӣҳои зуд-зуд ва кӯтоҳмуддат дорем, то намии хок дар сатҳи 60 то 70 фоизи қобилияти нигоҳ доҳии хок (сатҳи намии миёна) нигоҳ дошта шавад.</p>\n<ul>\n<li><strong>Ҳафтаи 1 то 3:</strong> Обёрӣ ҳар 2 то 3 рӯз бо ҳаҷми 10 то 15 литр дар соат (вобаста ба суръати даромади қатқатҳои об).</li>\n<li><strong>Моҳи дуюм:</strong> Кам кардани босирият ба ҳар 4 то 5 рӯз, аммо зиёд кардани ҳаҷми об то 20 то 25 литр.</li>\n<li><strong>Моҳи сеюм ва баъд аз он:</strong> Танзимонӣ мувофиқи шароити иқлимӣ ва чуқурии пайвастшавии решаҳо.</li>\n</ul>\n<h3>Идоракунии стресси камобӣ дар фаслҳои гуногун</h3>\n<p>Шоқофидар ба стресси камобн ҳассос аст, аммо хушкӣи зиёд метавонад ба афзоиши дарахторон зарар расонад. Баръакс, обёрории зиёд ба заҳалӣшавӣ ва камшавии шаҳбадии дарахторон оварда мерасонад. Истифодаи сенсорҳои намӣи хок барои назорати дақиқи ҳолати реша тавсия мешавад. Дар минтақаҳои гармӣ, обёрори дар саҳатҳои аввали субҳ беҳтар аст, то таҳқир ба ҳадди ақалл расад. Инчунин, дарки принсипҳои миқдори дарёфти термо сиёҳ дар ҳектар метавонад дарки беҳтари идоракунии стресси зистӣ дар оммавӣ истеҳсолиро эҷод кунад, зеро ҳарду ба мувозинати дақиқ байни манбаъҳои об ва афзоиши вобастаанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-مارچوبه-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت مارچوبه با آبیاری قطره‌ای - تصویر 2"/><figcaption>usuli ghafsi, ob boridagi chorik, tarikh ovari ob, marshubo</figcaption></figure>\n\n<h2>Масофаи ғаллӣ ва зичии ғаллаҳо</h2>\n<h3>Меъёрҳои муайян кардани масофаи байни сатрҳо ва дар сатр</h3>\n<p>Масофаи мувофиқ байни сатрҳо одатан 100 то 120 сантиметр ва масофа байни ғаллаҳо дар сатр 30 то 40 сантиметр аст. Ин масофаҳо имконияти гузариши ҳаво ва рӯшноиро фароҳам меоранд ва аз паҳншавии бемориҳои қамарӣ пешгирӣ менамоянд. Зичии зиёд сабаб мегардад, ки ғаллаҳо барои дастрасӣ ба манбаъҳо рақобат кунанд ва сифати пояҳои истеҳсолии кам шавад. Вақти ҳисоб кардани миқдори моли воридоти ва ғаллаҳо, дарки <a href="https://navar-abyari.ir/mikdori-tukhmi-havyz-dar-yek-ghektar-rohnamoi-purra/" target="_blank" rel="noopener">миқдори термо ҳайвонот дар як ҳектар (рахнамарги PRA)</a> ва дигар ғаллаҳо метавонад кӯмакрасон не бошад, зеро шоқофидар аз ғаллаи сабзӣ аст, аммо принсипҳои умумии зичии ғалла метавонад аз манбаъҳои умумӣ ба монанди рахнамарги <a href="https://navar-abyari.ir/six-row-barley-yield-per-hectare-increase-production/" target="_blank" rel="noopener">Афзоиши натиҷаи ҷӯи шашдаҳо дар ҳектар</a> Барои дарки роҳбарӣ кардани зичӣ истифода шавад.</p>\n<h3>Таъсири зичӣ ба ҳосили ниҳоӣ</h3>\n<p>Роҳбарӣ кардани зичии корам, бевосита ба ҳаҷми истеҳсоли қолаҳои фурӯшанда таъсир мерасонад. Зичии камтар боиси он мегардад, ки қолаҳо ғафстар ва бо сифати баландтар бошанд, ки дар бозорҳои экспортӣ қабулшавандагии бештар доранд. Дар баробари ин, зичии баланд истеҳсоли камарзишро зиёд мекунад. Интихоби стратегияи мувофиқ бояд асосан барои бозори ҳадафнок (дохилӣ ё экспортӣ) бошад.</p>\n\n<div class="image-container" id="image-3"></div>\n\n<h2>Нуқтаҳои амалӣ дар роҳбарии оройдодан ва чанордиҳӣ</h2>\n<ol>\n<li><strong>Шустани намакҳо:</strong> Дар охир ҳар даври оройдодан, барои шустани намакҳои ҷамъшуда дар сатҳи хок аз оби иловагӣ истифода баред, то аз ҷамъшавии намакҳо пешгирӣ гардад.</li>\n<li><strong>Чанордиҳи ҳамроҳ бо оройдодан (Fertigation):</strong> Системаҳои қатрагӣ имконияти иҷрои чанордиҳии ҳалшударо фароҳам меоранд. Чанорҳои нитрогенӣ дар марҳилаҳои ибтидоии рушд ва калийӣ дар марҳилаҳои ниҳоии истеҳсоли қола истифода шавад.</li>\n<li><strong>Низоби доб:</strong> Мунҳои тасмаи тирро мунтазам назорат кунед, то боварӣ ҳосл кунед, ки қисмҳои махравшуда ё шикаста нашудаанд. Махравии қатраандозҳо метавонад боиси парҳези ноинтиқоби об гардад, ки барои барҳи ҳассос марчуба фавтонангез аст.</li>\n</ol>\n<h3>Мудирати олакҳо дар хатти корт</h3>\n<p>Истифодаи малтич (пошиши рӯдӣ) дар хатти корт, ғайр аз кам кардани бухори об, рушди олакҳоро низ бозмедорад. Ин кор боиси мисоз, ки системаи оварии қатраандозӣ ба решаҳои мақсаднок диққат диҳад ва захираи растании вавоҳӣро нест кунад.</p>\n\n<h2>Саволҳои оммавӣ (FAQ)</h2>\n<h3>Оё оварии қатраандозӣ барои марҳилаҳои рушди тӯли марчуба мувофиқ аст?</h3>\n<p>Бале, системаҳои қатраандози доимӣ (Drip Line) барои солҳои дуюм баъд хеле муносибтар аз тасмаи тир якдафъабомаст мебошанд, зеро умри фоидаи баландтар доранд ва бо сохтори доими решаи марчуба, ки соли ба сол васеъ мешавад, мувофиқтар мебошанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-مارچوبه-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت مارچوبه با آبیاری قطره‌ای - تصویر 3"/><figcaption>usuli karkor doriqatara shiftnomai obvari murchuba</figcaption></figure>\n<h3>Барои ҳар як растак дар як рӯз чӣ қадар об кофӣ аст?</h3>\n<p>Моддаи дақиқ ба муҳити зист вобаста аст, аммо ба таври миёна дар фасли гармӣ барои ҳар як растак рӯзона аз 5 то 15 литр об лозим аст. Ин миқдор бояҳ тавассути ҳисоб кардани намии хок ва миқдори инкишоҳ (тавқур) танзим карда шавад.</p>\n<h3>Оё дар як системаи обёрӣ метавонанд чандин навъи сабзавотҳои гуногун пардохта шаванд?</h3>\n<p>Маслиҳат дода мешавад, ки вобаста ба эҳтиёҷоти обёрӣ ва босоти афзоиш гурӯҳбандӣ кунед. Ба суръати масалан, маълумот дар бораи <a href="https://navar-abyari.ir/millet-yield-per-hectare-guide-iraq-farmers/" target="_blank" rel="noopener">дораи ҳосилнокӣ ҷуворӣ дар як гектар (раҳнамо барои деҳқонони Ироқ)</a> нишон медиҳад, ки идоракунии сарчашмаҳои умумӣ ба нақшакашии дақиқи вақтӣ зарурат дорад, то эҳтиёҷоти гуногуни растаниҳо таъмин шаванд.</p>\n\n<h2>Хулоса</h2>\n<p>Пардохти чистони (марчубе) бо обёрии қатраиї ба даққат дар ҳамаи марҳилаҳо аз интихоби ток (худоро) то идоракунии ниҳоӣ лозим аст. Истифодаи системаҳои обёрии фишори баланд партофи сарчашмаҳои об, кам кардани хароҷоти корҳои ҷисмонӣ ва зиёд кардани ҳосилро бо худ меорад. Риояи расмиҳои дақиқ ва фазои муносиби бор кардан калиди муваффақият дар ин пардохти даимоӣ мебошад. Бо татбиқи асосии ин раҳнамо, шумо метавонед бо камтарин сарчашмаҳо сифат ва миқдори баланди маҳсулоти чистони таъмин кунед.</p>','Кӯмаки ҳамаҷониба дар ғаноши марчуби бо обёрӣ бо қатрагонӣ ва нӯрип','Дар ин мақолаи муфассал, мо принсипҳои кишт кардани спарожҳаро бо диққати махсус ба системҳои обёрии қатрагӣ ва пайпӣ баррасӣ мекунем. Бо хондани ин роҳнамо, шумо метавонед нақшаи дақиқтарро барои тайёрӣ кардани вақти обёрӣ, масофаи кишт ва идоракунии рушди рӯякро дар бар бигиред, то ки ба беҳтарин ҳосилдорӣ дастрас шавед.','publish','closed','closed','guide-ghanoshi-marjubi-obori-qatrangi-nuriip',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
